$ErrorActionPreference='Stop'; $root=Split-Path $PSScriptRoot -Parent; $out=Join-Path $root 'test-output'; if(Test-Path $out){Remove-Item $out -Recurse -Force}; dotnet build (Join-Path $root 'Backstop.csproj') -c Release --nologo -p:BaseIntermediateOutputPath="$out\obj\"; dotnet publish (Join-Path $root 'Backstop.csproj') -c Release -r win-x64 --self-contained true -p:PublishSingleFile=true -p:DebugType=None -o $out --nologo; $exe=Join-Path $out 'Backstop.exe'; if(!(Test-Path $exe)){throw 'Executable missing'}; $p=Start-Process $exe -PassThru; $deadline=(Get-Date).AddSeconds(10); do {Start-Sleep -Milliseconds 250; $p.Refresh(); if($p.HasExited){throw "Backstop exited with $($p.ExitCode)"}} while([string]::IsNullOrWhiteSpace($p.MainWindowTitle) -and (Get-Date)-lt $deadline); if([string]::IsNullOrWhiteSpace($p.MainWindowTitle)){Stop-Process $p.Id -Force; throw 'Main window did not appear'}; Stop-Process $p.Id -Force; Write-Host "PASS: build, publish, and launch ($($p.MainWindowTitle))"
